#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxScore(std::vector<int>& points, int m) {
        int n = points.size();
        if (m < n) return 0;

        auto is_possible = [&](long long min_val) -> bool {
            long long moves = 0;
            long long prev_moves = 0;
            for (int i = 0; i < n; ++i) {
                long long req = std::max(0LL, (min_val + points[i] - 1) / points[i] - prev_moves);
                if (req > 0) {
                    moves += 2 * req - 1;
                    prev_moves = req - 1;
                } else if (i + 1 < n) {
                    moves += 1;
                    prev_moves = 0;
                }
                if (moves > m) return false;
            }
            return true;
        };

        long long max_p = *std::max_element(points.begin(), points.end());
        long long l = 0;
        long long r = ((m + 1LL) / 2) * max_p + 1;
        long long ans = 0;

        while (l <= r) {
            long long mid = (l + r) / 2;
            if (is_possible(mid)) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }
};

class Solution {
    public long maxScore(int[] points, int m) {
        int n = points.length;
        if (m < n) return 0;

        long maxP = 0;
        for (int p : points) maxP = Math.max(maxP, p);

        long l = 0;
        long r = ((m + 1L) / 2) * maxP + 1;
        long ans = 0;

        while (l <= r) {
            long mid = (l + r) / 2;
            if (isPossible(points, m, n, mid)) {
                ans = mid;
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        return ans;
    }

    private boolean isPossible(int[] points, int m, int n, long minVal) {
        long moves = 0;
        long prevMoves = 0;
        for (int i = 0; i < n; i++) {
            long req = Math.max(0, (minVal + points[i] - 1) / points[i] - prevMoves);
            if (req > 0) {
                moves += 2 * req - 1;
                prevMoves = req - 1;
            } else if (i + 1 < n) {
                moves += 1;
                prevMoves = 0;
            }
            if (moves > m) return false;
        }
        return true;
    }
}

var maxScore = function(points, m) {
    const n = points.length;
    if (m < n) return 0;

    let maxP = 0;
    for (let i = 0; i < n; i++) {
        if (points[i] > maxP) maxP = points[i];
    }

    const bm = BigInt(m);
    const bn = BigInt(n);

    function isPossible(minVal) {
        let moves = 0n;
        let prevMoves = 0n;
        for (let i = 0; i < n; i++) {
            const pt = BigInt(points[i]);
            let req = (minVal + pt - 1n) / pt - prevMoves;
            if (req < 0n) req = 0n;
            if (req > 0n) {
                moves += 2n * req - 1n;
                prevMoves = req - 1n;
            } else if (i + 1 < n) {
                moves += 1n;
                prevMoves = 0n;
            }
            if (moves > bm) return false;
        }
        return true;
    }

    let l = 0n;
    let r = ((bm + 1n) / 2n) * BigInt(maxP) + 1n;
    let ans = 0n;

    while (l <= r) {
        const mid = (l + r) / 2n;
        if (isPossible(mid)) {
            ans = mid;
            l = mid + 1n;
        } else {
            r = mid - 1n;
        }
    }
    return Number(ans);
};
